import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-divider-cta-hero';
  group.position.set(-2.5, 0.7000000000000001, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const baseY = group.position.y;
  const timelines = [];
  let jewelMesh = null;

  const gltf = ctx.glbLoader.load('/prism-mock/home/nodes/cta-hero.glb');
  const meshRoot = gltf.scene ? gltf.scene.clone(true) : gltf;
  group.add(meshRoot);

  meshRoot.traverse((child) => {
    if (child.isMesh) {
      child.castShadow = true;
      child.receiveShadow = true;
      if (!jewelMesh || (child.geometry && child.geometry.boundingSphere && jewelMesh.geometry && child.geometry.boundingSphere.radius < jewelMesh.geometry.boundingSphere.radius)) {
        // heuristically pick smallest mesh as jewel accent
        if (!jewelMesh) jewelMesh = child;
      }
      if (child.material && !(child.material instanceof MeshStandardNodeMaterial)) {
        const mat = new MeshStandardNodeMaterial();
        mat.metalness = Math.min(child.material.metalness ?? 0.5, 0.55);
        mat.roughness = Math.max(child.material.roughness ?? 0.5, 0.5);
        mat.clearcoat = 0.2;
        mat.color = child.material.color ? child.material.color.clone() : color(0x16161d);
        mat.map = child.material.map || null;
        child.material = mat;
      }
    }
  });

  if (jewelMesh && jewelMesh.material) {
    jewelMesh.material.emissive = new THREE.Color(0xff2a38);
    jewelMesh.material.emissiveIntensity = 0.4;
  }

  // Hover: rise-in subtle (0.15 units)
  let hoverTl = null;
  const onHover = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    timelines.push(hoverTl);
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    timelines.push(hoverTl);
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  // Click: press-down + emit select event
  const onClick = () => {
    const pressTl = gsap.timeline();
    timelines.push(pressTl);
    pressTl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
    });

    if (ctx.emit) {
      ctx.emit('hub-home.select', { nodeId: 'home-divider-cta-hero' });
    }

    if (ctx.trpc && ctx.trpc.visits && ctx.trpc.visits.book) {
      ctx.trpc.visits.book.mutate({ slotIso: new Date().toISOString() })
        .then((result) => {
          group.userData.confirmPanel = result.slot;
        })
        .catch(() => {});
    }
  };

  group.userData.handlers = {
    onPointerOver: onHover,
    onPointerOut: onHoverOut,
    onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    meshRoot.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (child.material.map) child.material.map.dispose();
          child.material.dispose();
        }
      }
    });
    group.clear();
  };

  return group;
}
